import os
import shutil
import subprocess
import json
from pathlib import Path

REPO_PATH = "/workspace/repo/benchmark"
OUTPUT_PATH = "/output/InTAR"
STUBS_PATH = "/workspace/stubs"

def find_top_function(file_path):
    """Find the top function in a kernel file"""
    with open(file_path, 'r') as f:
        content = f.read()

    # Look for void function definitions that could be the top function
    # Usually the top function processes streams/mmaps
    lines = content.split('\n')
    for line in lines:
        line = line.strip()
        if line.startswith('void ') and '(' in line and not line.startswith('void read_') and not line.startswith('void write_'):
            func_name = line.split('(')[0].replace('void ', '').strip()
            if func_name and not func_name.startswith('_'):
                return func_name
    return None

def extract_hls_pragmas(file_path):
    """Extract HLS pragmas from a file"""
    pragmas = []
    with open(file_path, 'r') as f:
        for line in f:
            if '#pragma HLS' in line:
                pragmas.append(line.strip())
    return pragmas

def create_design_folder(design_name, source_files, design_info):
    """Create a design folder with all necessary files"""
    design_path = os.path.join(OUTPUT_PATH, design_name)
    os.makedirs(design_path, exist_ok=True)
    os.makedirs(os.path.join(design_path, 'src'), exist_ok=True)

    # Copy source files
    for src in source_files:
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(design_path, 'src'))

    # Copy stubs
    for stub in os.listdir(STUBS_PATH):
        shutil.copy2(os.path.join(STUBS_PATH, stub), os.path.join(design_path, 'src'))

    # Find top function
    top_func = None
    for src in source_files:
        if 'kernel' in src and top_func is None:
            top_func = find_top_function(src)

    # Generate info
    info = {
        'name': design_name,
        'top_function': top_func or 'Unknown',
        'files': [os.path.basename(f) for f in source_files],
        'description': design_info.get('description', '')
    }

    with open(os.path.join(design_path, 'design_info.json'), 'w') as f:
        json.dump(info, f, indent=2)

    return design_path, info

def generate_testbench(design_path, design_info):
    """Generate a basic testbench"""
    tb_content = f'''// Auto-generated testbench for {design_info['name']}
#include <iostream>
#include <cassert>
#include <cstdlib>
#include <ctime>

// Stub headers for HLS
#include "ap_int.h"
#include "ap_fixed.h"
#include "hls_stream.h"

// Include design source
#include "{design_info['files'][0]}"

int main() {{
    std::cout << "Running testbench for {design_info['name']}..." << std::endl;

    // TODO: Add specific test cases based on design requirements
    // This is a placeholder testbench

    std::cout << "Testbench completed." << std::endl;
    return 0;
}}
'''
    tb_path = os.path.join(design_path, 'src', 'testbench.cpp')
    with open(tb_path, 'w') as f:
        f.write(tb_content)
    return tb_path

def generate_readme(design_path, design_info):
    """Generate README.md for the design"""
    readme = f'''# {design_info['name']}

## Description
{design_info.get('description', 'HLS design from InTAR repository')}

## Top Function
`{design_info['top_function']}`

## Source Files
'''
    for f in design_info['files']:
        readme += f"- `{f}`\n"

    readme += '''
## Usage
To synthesize this design with Vitis HLS:
```bash
vitis_hls -f run_hls.tcl
```

## Notes
This design was extracted from the InTAR repository.
'''
    readme_path = os.path.join(design_path, 'README.md')
    with open(readme_path, 'w') as f:
        f.write(readme)
    return readme_path

def compile_design(design_path, design_info):
    """Compile the design with clang to check for errors"""
    src_dir = os.path.join(design_path, 'src')
    compile_log = os.path.join(design_path, 'compile_log.txt')

    # Find kernel and main cpp files (not host and not testbench)
    cpp_files = [f for f in os.listdir(src_dir) 
                 if f.endswith('.cpp') and 'host' not in f and 'testbench' not in f]

    if not cpp_files:
        with open(compile_log, 'w') as f:
            f.write("No suitable source files found for compilation.\n")
        return False

    # Try to compile each file
    errors = []
    warnings = []

    for cpp_file in cpp_files:
        src_file = os.path.join(src_dir, cpp_file)
        cmd = ['clang++', '-std=c++14', '-c', '-I' + src_dir, src_file, '-o', '/dev/null']

        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.returncode != 0:
                errors.append(f"Errors in {cpp_file}:")
                errors.append(result.stderr)
            elif result.stderr:
                warnings.append(f"Warnings in {cpp_file}:")
                warnings.append(result.stderr)
        except Exception as e:
            errors.append(f"Exception compiling {cpp_file}: {str(e)}")

    with open(compile_log, 'w') as f:
        if errors:
            f.write("=== COMPILATION ERRORS ===\n")
            f.write('\n'.join(errors))
        if warnings:
            f.write("\n=== COMPILATION WARNINGS ===\n")
            f.write('\n'.join(warnings))
        if not errors and not warnings:
            f.write("Compilation successful with no errors or warnings.\n")

    return len(errors) == 0

def generate_tcl_script(design_path, design_info):
    """Generate TCL synthesis script"""
    src_dir = os.path.join(design_path, 'src')

    # Find kernel files
    kernel_files = [f for f in os.listdir(src_dir) if f.endswith('.cpp') and 'host' not in f and 'testbench' not in f]

    tcl_content = f'''# Auto-generated TCL script for {design_info['name']}
set design_name "{design_info['name']}"
set top_func "{design_info['top_function']}"

# Create project
open_project -reset $design_name
set_top $top_func

# Add source files
'''
    for f in kernel_files:
        tcl_content += f'add_files "src/{f}"\n'

    tcl_content += f'''
# Add testbench
add_files -tb "src/testbench.cpp"

# Open solution
open_solution -reset "solution1"
set_part {{xcu280-fsvh2892-2L-e}}
create_clock -period 300MHz -name default

# Run synthesis
csynth_design

# Export design
export_design -format ip_catalog

exit
'''
    tcl_path = os.path.join(design_path, 'run_hls.tcl')
    with open(tcl_path, 'w') as f:
        f.write(tcl_content)
    return tcl_path

def create_manifest():
    """Create the final manifest"""
    manifest = {
        'repository': 'InTAR',
        'source': 'https://github.com/OswaldHe/InTAR.git',
        'designs': []
    }

    for design_name in os.listdir(OUTPUT_PATH):
        design_path = os.path.join(OUTPUT_PATH, design_name)
        if os.path.isdir(design_path):
            info_file = os.path.join(design_path, 'design_info.json')
            if os.path.exists(info_file):
                with open(info_file, 'r') as f:
                    info = json.load(f)
                manifest['designs'].append(info)

    manifest_path = os.path.join(OUTPUT_PATH, 'manifest.json')
    with open(manifest_path, 'w') as f:
        json.dump(manifest, f, indent=2)
    return manifest_path

